import React from 'react'
import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';


const TakeQuiz = () => {

        const location = useLocation();
        const { state: formData } = location;

        const [loading, setLoading] = useState(false);
        const [error, setError] = useState(null); // Error state for managing errors
        const [quizData, setQuizData] = useState(null); // Stores the full response
        const [responseText, setResponseText] = useState(""); // Stores the dynamically displayed text

        const prompt = `Generate a set of quiz questions having 4 choices and 1 correct answer based on the following data given in JSON format : 

        ${JSON.stringify(formData)} 

        Generate the questions in json format.`

        const fetchQuiz = async () => {
                console.log("Loading...");
                setLoading(true);
                try{
                        const response = await axios ({
                                url:"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=AIzaSyDzzLAYxe6PJiBrh_dL5B020aO6pIZx6NQ",
                                method:"post",
                                data:{
                                        contents:[{parts : [{text:prompt}]}],
                                },
                        });
                        console.log("Response : ", response);
                        setResponseText(response);

                        if (responseText.data && responseText.data.candidates.length > 0) {
                                // Extract the generated quiz text from the response
                                const content = responseText.data.candidates[0]?.content?.parts[0]?.text;
                                setQuizData(content);

                        }

                        else {
                                setError("No valid content returned from the API");
                              }

                } catch (err){
                        console.error("Error fetching quiz:", err);
                        setError("An error occurred while fetching the quiz questions.");
                }
                finally {
                        setLoading(false);
                }



        }

        useEffect(() => {
                if (formData){
                        fetchQuiz();
                }
        },[formData])


        return (
                <div>

                        {loading && <p>Loading...</p>}
                        {error && <p style={{ color: "red" }}>{error}</p>}
                        {quizData && (
                                <div>
                                        <h3>Quiz Questions</h3>
                                        <pre>{responseText}</pre>
                                </div>
                        )}

                </div>
        )

}

export default TakeQuiz
